CREATE TABLE learners(id TEXT PRIMARY KEY, label TEXT NOT NULL, synthetic INTEGER NOT NULL CHECK(synthetic=1)) STRICT;
CREATE TABLE subjects(id TEXT PRIMARY KEY, enabled INTEGER NOT NULL CHECK(enabled IN (0,1))) STRICT;
CREATE TABLE subject_states(learner_id TEXT NOT NULL REFERENCES learners(id), subject_id TEXT NOT NULL REFERENCES subjects(id), revision INTEGER NOT NULL CHECK(revision>=0), schema_version INTEGER NOT NULL CHECK(schema_version=1), content_version TEXT NOT NULL, projection TEXT NOT NULL CHECK(json_valid(projection) AND length(CAST(projection AS BLOB))<=4096), PRIMARY KEY(learner_id,subject_id)) STRICT;
CREATE TABLE server_attempts(id TEXT PRIMARY KEY, learner_id TEXT NOT NULL, subject_id TEXT NOT NULL, content_version TEXT NOT NULL, FOREIGN KEY(learner_id,subject_id) REFERENCES subject_states(learner_id,subject_id)) STRICT;
CREATE TABLE command_receipts(learner_id TEXT NOT NULL, command_id TEXT NOT NULL, subject_id TEXT NOT NULL, request_hash TEXT NOT NULL, committed_revision INTEGER NOT NULL, result_json TEXT NOT NULL CHECK(json_valid(result_json) AND length(CAST(result_json AS BLOB))<=16384), PRIMARY KEY(learner_id,command_id), FOREIGN KEY(learner_id,subject_id) REFERENCES subject_states(learner_id,subject_id)) STRICT;
CREATE TABLE learning_events(event_id TEXT PRIMARY KEY, learner_id TEXT NOT NULL, subject_id TEXT NOT NULL, command_id TEXT NOT NULL, revision INTEGER NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload) AND length(CAST(payload AS BLOB))<=16384), UNIQUE(learner_id,subject_id,revision), FOREIGN KEY(learner_id,command_id) REFERENCES command_receipts(learner_id,command_id)) STRICT;
CREATE INDEX events_subject_revision ON learning_events(learner_id,subject_id,revision);
CREATE TRIGGER immutable_events_update BEFORE UPDATE ON learning_events BEGIN SELECT RAISE(ABORT,'IMMUTABLE_EVENT'); END;
CREATE TRIGGER immutable_events_delete BEFORE DELETE ON learning_events BEGIN SELECT RAISE(ABORT,'IMMUTABLE_EVENT'); END;
CREATE TRIGGER immutable_receipts_update BEFORE UPDATE ON command_receipts BEGIN SELECT RAISE(ABORT,'IMMUTABLE_RECEIPT'); END;
CREATE TRIGGER immutable_receipts_delete BEFORE DELETE ON command_receipts BEGIN SELECT RAISE(ABORT,'IMMUTABLE_RECEIPT'); END;
CREATE TABLE media_assets(asset_id TEXT NOT NULL, version TEXT NOT NULL, manifest TEXT NOT NULL CHECK(json_valid(manifest) AND length(CAST(manifest AS BLOB))<=8192), PRIMARY KEY(asset_id,version)) STRICT;
CREATE TABLE content_manifests(subject_id TEXT NOT NULL REFERENCES subjects(id), content_version TEXT NOT NULL, manifest TEXT NOT NULL CHECK(json_valid(manifest) AND length(CAST(manifest AS BLOB))<=65536), PRIMARY KEY(subject_id,content_version)) STRICT;
CREATE TABLE content_media_refs(subject_id TEXT NOT NULL, content_version TEXT NOT NULL, asset_id TEXT NOT NULL, asset_version TEXT NOT NULL, PRIMARY KEY(subject_id,content_version,asset_id,asset_version), FOREIGN KEY(subject_id,content_version) REFERENCES content_manifests(subject_id,content_version), FOREIGN KEY(asset_id,asset_version) REFERENCES media_assets(asset_id,version)) STRICT;
CREATE TABLE audit_log(id INTEGER PRIMARY KEY, action TEXT NOT NULL, at TEXT NOT NULL, metadata TEXT NOT NULL CHECK(json_valid(metadata) AND length(CAST(metadata AS BLOB))<=4096)) STRICT;
